<template>
  <div class="plot-management">
    <!-- Header -->
    <header class="page-header bg-gradient-primary text-white py-4 mb-4">
      <div class="container">
        <div class="row align-items-center">
          <div class="col-lg-8">
            <h5 class="fw-bold mb-2">
              <i class="bi bi-geo-alt me-2"></i>Plot Management
            </h5>
            <p class="mb-0 opacity-75">
              Register, edit, and manage virtual land plots. Click on plots to select them.
            </p>
          </div>
          <div class="col-lg-4 mt-3 mt-lg-0">
            <div class="card bg-white bg-opacity-10 border-0">
              <div class="card-body p-3">
                <div class="d-flex justify-content-between align-items-center">
                  <div>
                    <small class="text-white">Total Plots</small>
                    <div class="h4 mb-0 fw-bold text-white">{{ plots.length }}</div>
                  </div>
                  <div class="bg-white bg-opacity-25 rounded-circle p-2">
                    <i class="bi bi-layers fs-5"></i>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </header>

    <!-- Main Content -->

      <div class="row">
        <!-- Left Column: SVG Visualization -->
        <div class="col-lg-8">
          <!-- Controls Bar -->
          <div class="card border-0 shadow-sm mb-3">
            <div class="card-body py-3">
              <div class="d-flex flex-wrap justify-content-between align-items-center">
                <div>
                  <h5 class="card-title mb-0">
                    <i class="bi bi-map me-2 text-primary"></i>
                    Plot Visualization
                  </h5>
                </div>
                <div class="btn-group" role="group">
                  <button 
                    v-if="!selectedPlot"
                    type="button" 
                    class="btn btn-primary"
                    data-bs-toggle="modal" 
                    data-bs-target="#addPlotModal"
                    :disabled="register_plot"
                  >
                    <i class="bi bi-plus-circle me-2"></i>
                    Add Plot
                  </button>
                  
                  <button 
                    v-if="selectedPlot && selectedPlot.status === 'available'"
                    @click="edit_plot = !edit_plot"
                    type="button" 
                    class="btn btn-secondary"
                  >
                    <i :class="edit_plot ? 'bi bi-x-circle' : 'bi bi-pencil'"></i>
                    {{ edit_plot ? 'Cancel Edit' : 'Edit Plot' }}
                  </button>
                  
                  <button 
                    v-if="selectedPlot && selectedPlot.status !== 'sold'"
                    type="button" 
                    class="btn btn-success"
                    @click="sellPlot()"
                  >
                    <i class="bi bi-check-circle me-2"></i>
                    Mark as Sold
                  </button>
                </div>
              </div>
            </div>
          </div>


<!-- SVG Container -->
<div class="card border-0 shadow-sm">
  <div class="card-body p-0">

    <!-- Zoom Controls Bar -->
    <div class="d-flex align-items-center gap-2 px-3 py-2 border-bottom bg-light">
      <small class="text-muted me-1">Zoom:</small>
      <button class="btn btn-sm btn-outline-secondary" @click="zoomOut" :disabled="zoomLevel <= zoomMin">
        <i class="bi bi-dash-lg"></i>
      </button>
      <input
        type="range"
        class="form-range"
        style="width: 120px;"
        :min="zoomMin"
        :max="zoomMax"
        :step="zoomStep"
        v-model.number="zoomLevel"
      >
      <button class="btn btn-sm btn-outline-secondary" @click="zoomIn" :disabled="zoomLevel >= zoomMax">
        <i class="bi bi-plus-lg"></i>
      </button>
      <span class="badge bg-primary ms-1" style="min-width:48px;">{{ Math.round(zoomLevel * 100) }}%</span>
      <button class="btn btn-sm btn-outline-secondary ms-1" @click="zoomReset" title="Reset zoom">
        <i class="bi bi-arrow-counterclockwise"></i>
      </button>

        <button class="btn btn-sm btn-success ms-auto" @click="downloadSvg" title="Download SVG">
    <i class="bi bi-download me-1"></i>
    Download SVG
  </button>

    </div>

<div class="svg-scroll-wrapper">
  <div :style="{ transform: `scale(${zoomLevel})`, transformOrigin: 'top left', transition: 'transform 0.15s ease' }">
    <svg
      :width="svgWidth + 'px'"
      :height="svgHeight + 'px'"
      :viewBox="'0 0 ' + svgWidth + ' ' + svgHeight"
      preserveAspectRatio="xMidYMid meet"
      @click="handleSvgClick($event)"
      class="plot-svg"
    >
      <!-- Definitions -->
      <defs>
        <pattern id="gridPattern" width="50" height="50" patternUnits="userSpaceOnUse">
          <path d="M 50 0 L 0 0 0 50" fill="none" stroke="#e9ecef" stroke-width="1"/>
        </pattern>
      </defs>
      
      <!-- Background Grid -->
      <rect :width="svgWidth" :height="svgHeight" fill="url(#gridPattern)"/>
      
      <!-- Plot Polygons and Elements -->
      <template v-for="(plot, index) in plots" :key="plot.id">
        <!-- Create clip path for this plot -->
        <defs>
          <clipPath :id="`clip-${plot.id}`">
            <polygon :points="plotPoints(plot)"/>
          </clipPath>
        </defs>
        
        <!-- Shaded areas filled with solid color (before polygon to appear behind) -->
        <g v-if="plot.connectors && plot.connectors.length > 0">
<template v-for="connector in plot.connectors" :key="`shaded-${connector.id}`">
  <template v-for="(poly, i) in getShadedPolygonPoints(plot, connector)" :key="i">
    <polygon
      :points="poly"
      :clip-path="`url(#clip-${plot.id})`"
      fill="#00BCD4"
      fill-opacity="0.3"
      pointer-events="none"
    />
  </template>
</template>
        </g>
        
        <!-- Plot Shape (base fill) -->
        <polygon
          :points="plotPoints(plot)"
          :fill="getPlotFill(plot)"
          :stroke="getPlotStroke(plot)"
          stroke-width="2"
          :class="['plot-polygon', plot.status === 'sold' ? 'plot-sold' : 'plot-available']"
          @click="selectPlot(plot)"
        />
        
        <!-- Connector Lines -->
        <line
          v-for="c in plot.connectors"
          :key="c.id"
          :x1="parseFloat(c.start_x) - xOffset"
          :y1="parseFloat(c.start_y) - yOffset"
          :x2="parseFloat(c.end_x) - xOffset"
          :y2="parseFloat(c.end_y) - yOffset"
          stroke-width="2"
          stroke-dasharray="6,4"
          :class="getConnectorClass(c.type)"
        />
        
        <!-- Plot Label -->
        <text
          :x="plotCenter(plot).x"
          :y="plotCenter(plot).y"
          text-anchor="middle"
          :fill="getPlotTextColor(plot)"
          class="plot-label"
          pointer-events="none"
        >
          {{ plot.name }}
          <tspan 
            v-if="plot.status === 'sold'" 
            :x="plotCenter(plot).x" 
            dy="1.2em"
            font-size="10"
            class="sold-label"
          >
            (Sold)
          </tspan>
        </text>
        
        <!-- Distance Labels -->
        <template v-for="(p, i) in plot.coordinates" :key="`distance-${plot.id}-${i}`">
          <text
            :x="lineLabelPosition(p, plot.coordinates[(i+1)%plot.coordinates.length], plotCenter(plot)).x"
            :y="lineLabelPosition(p, plot.coordinates[(i+1)%plot.coordinates.length], plotCenter(plot)).y"
            text-anchor="middle"
            fill="#666"
            font-size="10"
            class="distance-label"
            pointer-events="none"
          >
            {{ Math.round(lineDistance(p, plot.coordinates[(i+1)%plot.coordinates.length])) }}m
          </text>
        </template>
        
        <!-- Nodes (Visible when editing or selected) -->
        <template v-if="selectedPlot && selectedPlot.id === plot.id && (edit_plot || register_plot)">
          <circle
            v-for="(p, i) in plot.coordinates"
            :key="`node-${plot.id}-${i}`"
            :cx="p.x - xOffset"
            :cy="p.y - yOffset"
            :r="getNodeRadius(i)"
            :fill="getNodeFill(i)"
            stroke="white"
            stroke-width="1.5"
            class="plot-node"
            @click="selectNode(plot, i)"
          />
        </template>
      </template>
    </svg>
  </div>
</div>
    
    <!-- Legend -->
    <div class="legend p-3 border-top">
      <div class="d-flex flex-wrap gap-3">
        <div class="d-flex align-items-center">
          <div class="legend-dot available me-2"></div>
          <small class="text-muted">Available</small>
        </div>
        <div class="d-flex align-items-center">
          <div class="legend-dot sold me-2"></div>
          <small class="text-muted">Sold</small>
        </div>
        <div class="d-flex align-items-center">
          <div class="legend-dot selected me-2"></div>
          <small class="text-muted">Selected</small>
        </div>
        <div class="d-flex align-items-center">
          <div class="legend-dot node me-2"></div>
          <small class="text-muted">Editable Node</small>
        </div>
      </div>
    </div>

  </div>
</div>
        </div>

        <!-- Right Column: Plot Details -->
        <div class="col-lg-4 mt-4 mt-lg-0">
          <div class="sticky-sidebar">
            <!-- Selected Plot Card -->
            <div class="card border-0 shadow-sm mb-3" v-if="selectedPlot">
              <div :class="['card-header text-white', selectedPlot.status === 'sold' ? 'bg-secondary' : 'bg-primary']">
                <div class="d-flex justify-content-between align-items-center">
                  <h5 class="card-title mb-0 text-white">
                    <i :class="selectedPlot.status === 'sold' ? 'bi bi-archive' : 'bi bi-geo-alt'"></i>
                    Plot Details
                  </h5>
                  <span :class="`badge ${selectedPlot.status === 'sold' ? 'bg-light text-dark' : 'bg-light text-primary'}`">
                    {{ selectedPlot.status === 'sold' ? 'Sold' : 'Available' }}
                  </span>
                </div>
              </div>
              
              <div class="card-body">
                <!-- Plot Information -->
                <div class="plot-info mb-4">
                  <div class="info-grid mb-3">
                    <div class="info-item">
                      <small class="text-muted d-block">Plot Name</small>
                      <div class="d-flex align-items-center">
                        <input 
                          v-if="edit_plot_name" 
                          type="text" 
                          class="form-control form-control-sm" 
                          v-model="selectedPlot.name"
                          @keyup.enter="edit_plot_name = false"
                        >
                        <strong v-else>{{ selectedPlot.name }}</strong>
                        <button 
                          v-if="edit_plot && selectedPlot.status !== 'sold'"
                          class="btn btn-link btn-sm ms-2"
                          @click="edit_plot_name = !edit_plot_name"
                        >
                          <i :class="`bi ${edit_plot_name ? 'bi-check' : 'bi-pencil'}`"></i>
                        </button>
                      </div>
                    </div>
                    
                    <div class="info-item">
                      <small class="text-muted d-block">Size</small>
                      <div class="h5 mb-0 text-primary">
                        {{ areaKm2(selectedPlot.coordinates).toFixed(4) }}
                        <small class="text-muted">km²</small>
                      </div>
                    </div>
                    
                    <div class="info-item">
                      <small class="text-muted d-block">Nodes</small>
                      <div class="d-flex align-items-center">
                        <span class="h5 mb-0 me-2">{{ selectedPlot.coordinates.length }}</span>
                      </div>
                    </div>

                       <div class="info-item">
                      <small class="text-muted d-block">Price Per km²</small>
                      <div class="d-flex align-items-center">
                        <span class="h5 mb-0 me-2">Tsh 17,000/=</span>
                      </div>
                    </div>

                    

                  </div>

                     <div class="info-item">
                      <small class="text-muted d-block">Total Plot Price</small>
                      <div class="d-flex align-items-center">
                        <span class="h5 mb-0 me-2">Tsh {{(areaKm2(selectedPlot.coordinates) * 17000).toLocaleString() }}/=</span>
                      </div>
                    </div>
                  
                  <!-- Scale Control -->
                  <div class="scale-control mb-3">
                    <label class="form-label">
                      <i class="bi bi-rulers me-1"></i>
                      Scale (Max Value)
                    </label>
                    <input 
                      type="number" 
                      class="form-control" 
                      v-model.number="scaleValue" 
                      placeholder="Enter scale"
                      min="100"
                      max="2000"
                    >
                  </div>
                  
                  <!-- Selected Node Controls -->
                  <div v-if="selected_node.nodeIndex !== null && (edit_plot || register_plot)" class="node-controls bg-light p-3 rounded mb-3">
                    <h6 class="mb-3">
                      <i class="bi bi-gear me-2"></i>
                      Editing Node {{ selected_node.nodeIndex + 1 }}
                    </h6>
                    
                    <div class="mb-3">
                      <label class="form-label small">X Position (Longitude)</label>
                      <div class="d-flex align-items-center">
                        <input 
                          type="range" 
                          class="form-range flex-grow-1 me-2" 
                          min="0" 
                          :max="scaleValue" 
                          v-model.number="longitudeValue"
                        >
                        <span class="badge bg-primary">{{ longitudeValue }}</span>
                      </div>
                    </div>
                    
                    <div class="mb-3">
                      <label class="form-label small">Y Position (Latitude)</label>
                      <div class="d-flex align-items-center">
                        <input 
                          type="range" 
                          class="form-range flex-grow-1 me-2" 
                          min="0" 
                          :max="scaleValue" 
                          v-model.number="latitudeValue"
                        >
                        <span class="badge bg-primary">{{ latitudeValue }}</span>
                      </div>
                    </div>

                    <!-- Distance to Next Node -->
                    <div class="mb-3 pt-3 border-top">
                      <label class="form-label small">
                        <i class="bi bi-arrow-right me-1"></i>
                        Distance to Next Node (m)
                      </label>
                      <div class="d-flex align-items-center gap-2">
                        <input 
                          type="number" 
                          class="form-control form-control-sm" 
                          min="10" 
                          max="500"
                          :value="distanceToNextInput"
                          @input="adjustDistanceToNext($event)"
                          placeholder="Enter distance"
                        >
                        <span class="badge bg-info ms-1" style="min-width: 50px;">{{ Math.round(getDistanceToNextNode()) }}m</span>
                      </div>
                      <small class="text-muted d-block mt-2">
                        Node {{ selected_node.nodeIndex + 1 }} → Node {{ (selected_node.nodeIndex + 1) % selectedPlot.coordinates.length + 1 }}
                      </small>
                    </div>

                    <!-- Distance to Previous Node -->
                    <div class="mb-3">
                      <label class="form-label small">
                        <i class="bi bi-arrow-left me-1"></i>
                        Distance to Previous Node (m)
                      </label>
                      <div class="d-flex align-items-center gap-2">
                        <input 
                          type="number" 
                          class="form-control form-control-sm" 
                          min="10" 
                          max="500"
                          :value="distanceToPreviousInput"
                          @input="adjustDistanceToPrevious($event)"
                          placeholder="Enter distance"
                        >
                        <span class="badge bg-info ms-1" style="min-width: 50px;">{{ Math.round(getDistanceToPreviousNode()) }}m</span>
                      </div>
                      <small class="text-muted d-block mt-2">
                        Node {{ selected_node.nodeIndex }} → Node {{ selected_node.nodeIndex + 1 }}
                      </small>
                    </div>
                  </div>
                </div>
                
                <!-- Action Buttons -->
                <div class="action-buttons">
                  <template v-if="register_plot || edit_plot">
                <div class="d-grid gap-2">
  <div class="btn-group gap-2" role="group">
    <button 
      class="btn btn-danger"
      @click="clearForm"
    >
      <i class="bi bi-x-circle me-2"></i>
      Cancel 
    </button>

    <button 
      class="btn btn-danger"
      @click="deleteNode()"
      v-if="selected_node.nodeIndex"
      :disabled="selectedPlot.coordinates.length < 4"
    >
      <i class="bi bi-trash me-2"></i>
      Delete Node
    </button>

      <button 
      class="btn btn-primary"
      @click="addNode()"
    >
      <i class="bi bi-plus-square me-2"></i>
      Add Node
    </button>
  </div>

  <button 
    v-if="register_plot"
    class="btn btn-primary"
    @click="registerPlot"
  >
    <i class="bi bi-save me-2"></i>
    Save Plot
  </button>

  <button 
    v-if="edit_plot"
    class="btn btn-success"
    @click="updatePlot"
  >
    <i class="bi bi-check-circle me-2"></i>
    Update Plot
  </button>
</div>

                  </template>
                  
                  <div v-else class="text-center">
                    <small class="text-muted">
                      Select a plot and enable edit mode to make changes
                    </small>
                  </div>
                </div>
              </div>
            </div>
            
            <!-- No Plot Selected -->
            <div class="card border-0 shadow-sm text-center py-5" v-else>
              <div class="card-body">
                <div class="mb-3">
                  <i class="bi bi-geo text-muted display-6"></i>
                </div>
                <h5 class="text-muted mb-3">No Plot Selected</h5>
                <p class="text-muted small mb-0">
                  Click on any plot in the visualization area to view and edit its details.
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>

  </div>

  <!-- Add Plot Modal -->
  <div class="modal fade" id="addPlotModal" tabindex="-1">
    <div class="modal-dialog modal-dialog-centered">
      <div class="modal-content">
        <div class="modal-header bg-primary text-white">
          <h5 class="modal-title">
            <i class="bi bi-plus-circle me-2"></i>
            Add New Plot
          </h5>
          <button type="button" class="btn-close btn-close-white" data-bs-dismiss="modal"></button>
        </div>
        <div class="modal-body">
          <div class="mb-3">
            <label class="form-label">Plot Name</label>
            <input 
              type="text" 
              class="form-control" 
              placeholder="Enter plot name"
              v-model="plot_name"
              @keyup.enter="newPlot"
            >
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button>
          <button 
            type="button" 
            class="btn btn-primary" 
            data-bs-dismiss="modal" 
            :disabled="!plot_name" 
            @click="newPlot"
          >
            <i class="bi bi-plus-circle me-2"></i>
            Create Plot
          </button>
        </div>
      </div>
    </div>
  </div>

  <!-- Toast Notification -->
  <div class="toast-container position-fixed bottom-0 end-0 p-3">
    <div 
      id="plotToast" 
      class="toast align-items-center border-0 text-bg-success" 
      role="alert" 
      aria-live="assertive" 
      aria-atomic="true"
    >
      <div class="d-flex">
        <div class="toast-body d-flex align-items-center">
          <i class="bi bi-check-circle me-2"></i>
          <span id="plotToastMessage">Operation completed successfully</span>
        </div>
        <button 
          type="button" 
          class="btn-close btn-close-white me-2 m-auto" 
          data-bs-dismiss="toast" 
          aria-label="Close"
        ></button>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, onMounted, watch, inject } from 'vue'
import axios from 'axios'
const showMessage = inject('showMessage')
const showError = inject('showError')
// Constants
const PX_TO_METER = 65.0
    const axiosInstance = axios.create({
       baseURL: process.env.VUE_APP_API_BASE_URL
})

// Refs
const plots = ref([])
const selectedPlot = ref(null)
const plot_name = ref('')
const register_plot = ref(false)
const edit_plot = ref(false)
const edit_plot_name = ref(false)
const scaleValue = ref(500)
const longitudeValue = ref(250)
const latitudeValue = ref(250)
const distanceToNextInput = ref('')
const distanceToPreviousInput = ref('')
const selected_node = ref({ plotIndex: null, nodeIndex: null, label: 'none' })



const zoomLevel = ref(1)
const zoomMin = 0.3
const zoomMax = 3
const zoomStep = 0.1

const zoomIn = () => { zoomLevel.value = Math.min(zoomMax, +(zoomLevel.value + zoomStep).toFixed(1)) }
const zoomOut = () => { zoomLevel.value = Math.max(zoomMin, +(zoomLevel.value - zoomStep).toFixed(1)) }
const zoomReset = () => { zoomLevel.value = 1 }

const deleteNode = () => {
  const pIdx = selected_node.value.plotIndex
  const nIdx = selected_node.value.nodeIndex
  
  if (pIdx !== null && nIdx !== null && plots.value[pIdx].coordinates.length > 3) {
    plots.value[pIdx].coordinates.splice(nIdx, 1)
    selected_node.value = { plotIndex: null, nodeIndex: null, label: 'none' }
  }
}
// Computed Properties
const svgWidth = computed(() => {
  if (!plots.value.length) return 1200
  let minX = Infinity, maxX = 0
  plots.value.forEach(plot => {
    plot.coordinates.forEach(p => {
      if (p.x > maxX) maxX = p.x
      if (p.x < minX) minX = p.x
    })
  })
  return (maxX - minX) + 250 // width = actual span + padding
})

const svgHeight = computed(() => {
  if (!plots.value.length) return 800
  let minY = Infinity, maxY = 0
  plots.value.forEach(plot => {
    plot.coordinates.forEach(p => {
      if (p.y > maxY) maxY = p.y
      if (p.y < minY) minY = p.y
    })
  })
  return (maxY - minY) + 250
})

// Helper Functions
const polygonAreaFromDistances = (coordinates) => {
  let area = 0
  const n = coordinates.length
  for (let i = 0; i < n; i++) {
    const x1 = coordinates[i].x * PX_TO_METER
    const y1 = coordinates[i].y * PX_TO_METER
    const x2 = coordinates[(i + 1) % n].x * PX_TO_METER
    const y2 = coordinates[(i + 1) % n].y * PX_TO_METER
    area += x1 * y2 - x2 * y1
  }
  return Math.abs(area) / 2
}

const areaKm2 = (coords) => polygonAreaFromDistances(coords) / 1_000_000

const plotPoints = (plot) =>
  plot.coordinates.map(p => `${p.x - xOffset.value},${p.y - yOffset.value}`).join(' ')

const plotCenter = (plot) => {
  const x = plot.coordinates.reduce((s, p) => s + p.x, 0) / plot.coordinates.length
  const y = plot.coordinates.reduce((s, p) => s + p.y, 0) / plot.coordinates.length
  return { x: x - xOffset.value, y: y - yOffset.value }
}

const lineLabelPosition = (p1, p2, center) => {
  const midX = (p1.x + p2.x) / 2 - xOffset.value
  const midY = (p1.y + p2.y) / 2 - yOffset.value
  const offsetX = (center.x - midX) * 0.2
  const offsetY = (center.y - midY) * 0.2
  return { x: midX + offsetX, y: midY + offsetY }
}



const lineDistance = (p1, p2) => {
  return Math.hypot((p2.x - p1.x) * PX_TO_METER, (p2.y - p1.y) * PX_TO_METER)
}

// Distance adjustment helpers
const getDistanceToNextNode = () => {
  if (selected_node.value.nodeIndex === null || !selectedPlot.value) return 0
  const nIdx = selected_node.value.nodeIndex
  const nextIdx = (nIdx + 1) % selectedPlot.value.coordinates.length
  return lineDistance(selectedPlot.value.coordinates[nIdx], selectedPlot.value.coordinates[nextIdx])
}

const getDistanceToPreviousNode = () => {
  if (selected_node.value.nodeIndex === null || !selectedPlot.value) return 0
  const nIdx = selected_node.value.nodeIndex
  const prevIdx = (nIdx - 1 + selectedPlot.value.coordinates.length) % selectedPlot.value.coordinates.length
  return lineDistance(selectedPlot.value.coordinates[prevIdx], selectedPlot.value.coordinates[nIdx])
}

const adjustDistanceToNext = (event) => {
  if (selected_node.value.nodeIndex === null || !selectedPlot.value) return
  
  const targetDistance = parseFloat(event.target.value)
  if (isNaN(targetDistance) || targetDistance <= 0) return
  
  distanceToNextInput.value = event.target.value
  
  const nIdx = selected_node.value.nodeIndex
  const nextIdx = (nIdx + 1) % selectedPlot.value.coordinates.length
  
  const currentNode = selectedPlot.value.coordinates[nIdx]
  const nextNode = selectedPlot.value.coordinates[nextIdx]
  
  // Get direction angle from current to next
  const dx = nextNode.x - currentNode.x
  const dy = nextNode.y - currentNode.y
  const angle = Math.atan2(dy, dx)
  
  // Convert target distance (meters) to pixels
  const targetPixels = targetDistance / PX_TO_METER
  
  // Position next node at exact distance along the angle
  nextNode.x = currentNode.x + targetPixels * Math.cos(angle)
  nextNode.y = currentNode.y + targetPixels * Math.sin(angle)
}

const adjustDistanceToPrevious = (event) => {
  if (selected_node.value.nodeIndex === null || !selectedPlot.value) return
  
  const targetDistance = parseFloat(event.target.value)
  if (isNaN(targetDistance) || targetDistance <= 0) return
  
  distanceToPreviousInput.value = event.target.value
  
  const nIdx = selected_node.value.nodeIndex
  const prevIdx = (nIdx - 1 + selectedPlot.value.coordinates.length) % selectedPlot.value.coordinates.length
  
  const currentNode = selectedPlot.value.coordinates[nIdx]
  const prevNode = selectedPlot.value.coordinates[prevIdx]
  
  // Get direction angle from previous to current
  const dx = currentNode.x - prevNode.x
  const dy = currentNode.y - prevNode.y
  const angle = Math.atan2(dy, dx)
  
  // Convert target distance (meters) to pixels
  const targetPixels = targetDistance / PX_TO_METER
  
  // Position current node at exact distance along the angle
  currentNode.x = prevNode.x + targetPixels * Math.cos(angle)
  currentNode.y = prevNode.y + targetPixels * Math.sin(angle)
  
  longitudeValue.value = currentNode.x
  latitudeValue.value = currentNode.y
}


// Generate shaded polygon that extends from connector to SVG boundaries
const shadings = {
  // break_shade: both, left, right, or none
  // left_node_shade: none, left, right, or both
  // right_node_shade: none, left, right, or both
  
  shading1: { break_shade: 'both', left_node_shade: 'none', right_node_shade: 'none' },
  shading2: { break_shade: 'both', left_node_shade: 'left', right_node_shade: 'right' },
  shading3: { break_shade: 'left', left_node_shade: 'both', right_node_shade: 'none' },
  shading4: { break_shade: 'right', left_node_shade: 'none', right_node_shade: 'both' },
  shading5: { break_shade: 'left', left_node_shade: 'left', right_node_shade: 'left' },
  shading6: { break_shade: 'right', left_node_shade: 'right', right_node_shade: 'right' },
  shadingn: { break_shade: 'right', left_node_shade: 'right', right_node_shade: 'none' }
}

const getShadedPolygonPoints = (plot, connector) => {
  const startX = parseFloat(connector.start_x)
  const startY = parseFloat(connector.start_y)
  const endX = parseFloat(connector.end_x)
  const endY = parseFloat(connector.end_y)

  const dx = endX - startX
  const dy = endY - startY
  const length = Math.hypot(dx, dy)

  if (length === 0) return []

  const connX = dx / length
  const connY = dy / length

  const perpX = -dy / length
  const perpY = dx / length

  const config = shadings[connector.shading_type || 'shadingn']
  const breakSign = config.break_shade === 'left' ? 1 : config.break_shade === 'right' ? -1 : 0

  const ext = 100000

  const extStartX = startX - connX * ext
  const extStartY = startY - connY * ext
  const extEndX = endX + connX * ext
  const extEndY = endY + connY * ext

  let polygons = []

  const build = (points) => {
    return points.map(p => `${p.x - xOffset.value},${p.y - yOffset.value}`).join(' ')
  }

  // Break shading
  if (config.break_shade !== 'none') {
    const sign = breakSign === 0 ? [1, -1] : [breakSign]

    sign.forEach(s => {
      polygons.push(build([
        { x: startX, y: startY },
        { x: endX, y: endY },
        { x: extEndX + perpX * ext * s, y: extEndY + perpY * ext * s },
        { x: extStartX + perpX * ext * s, y: extStartY + perpY * ext * s }
      ]))
    })
  }

  // Left node
  if (config.left_node_shade !== 'none') {
    const shades = config.left_node_shade === 'both' ? [1, -1] :
                   config.left_node_shade === 'left' ? [1] : [-1]

    shades.forEach(s => {
      polygons.push(build([
        { x: startX, y: startY },
        { x: extStartX, y: extStartY },
        { x: extStartX + perpX * ext * s, y: extStartY + perpY * ext * s },
        { x: startX + perpX * ext * s, y: startY + perpY * ext * s }
      ]))
    })
  }

  // Right node
  if (config.right_node_shade !== 'none') {
    const shades = config.right_node_shade === 'both' ? [1, -1] :
                   config.right_node_shade === 'left' ? [1] : [-1]

    shades.forEach(s => {
      polygons.push(build([
        { x: endX, y: endY },
        { x: extEndX, y: extEndY },
        { x: extEndX + perpX * ext * s, y: extEndY + perpY * ext * s },
        { x: endX + perpX * ext * s, y: endY + perpY * ext * s }
      ]))
    })
  }

  return polygons
}


// Style Helpers
const getPlotFill = (plot) => {
  if (selectedPlot.value && selectedPlot.value.id === plot.id) {
    return plot.status === 'sold' ? 'rgba(220, 53, 69, 0.2)' : 'rgba(13, 110, 253, 0.2)'
  }
  return plot.status === 'sold' ? 'rgba(220, 53, 69, 0.1)' : 'rgba(40, 167, 69, 0.1)'
}

const getPlotStroke = (plot) => {
  if (selectedPlot.value && selectedPlot.value.id === plot.id) {
    return plot.status === 'sold' ? '#dc3545' : '#0d6efd'
  }
  return plot.status === 'sold' ? '#dc3545' : '#28a745'
}

const getPlotTextColor = (plot) => {
  if (selectedPlot.value && selectedPlot.value.id === plot.id) {
    return plot.status === 'sold' ? '#dc3545' : '#0d6efd'
  }
  return plot.status === 'sold' ? '#6c757d' : '#212529'
}

const getNodeRadius = (index) => {
  return selected_node.value.nodeIndex === index ? 4 : 3
}

const getNodeFill = (index) => {
  return selected_node.value.nodeIndex === index ? '#dc3545' : '#ffc107'
}

// Core Functions
const selectPlot = (plot) => {
      if(register_plot.value || edit_plot.value){
            return ;
      }
  if (plot.status === 'sold' && !(selectedPlot.value && selectedPlot.value.id === plot.id)) {
    showError('This plot is sold and cannot be edited', 'warning', 'bi-exclamation-triangle')
  }
  
  if (selectedPlot.value && selectedPlot.value.id === plot.id) {
    clearForm()
  } else {
    selectedPlot.value = plot
    edit_plot.value = false
    edit_plot_name.value = false
    selected_node.value = { plotIndex: null, nodeIndex: null, label: 'none' }
  }
}

const selectNode = (plot, index) => {
  if ((!edit_plot.value && !register_plot.value) || !selectedPlot.value || selectedPlot.value.id !== plot.id) {
    return
  }

  const plotIdx = plots.value.findIndex(p => p.id === plot.id)

  if (selected_node.value.plotIndex === plotIdx && selected_node.value.nodeIndex === index) {
    selected_node.value = { plotIndex: null, nodeIndex: null, label: 'none' }
    return
  }

  selected_node.value = { plotIndex: plotIdx, nodeIndex: index, label: `${plot.name}-${index}` }
  longitudeValue.value = plot.coordinates[index].x
  latitudeValue.value = plot.coordinates[index].y
}

const newPlot = () => {
  register_plot.value = true
  plots.value.push({
    id: 0,
    name: plot_name.value,
    color_fill: '#e3f2fd',
    color_stroke: '#1976d2',
    status: 'available',
    coordinates: [
      { x: 600, y: 10 },
      { x: 750, y: 10 },
      { x: 750, y: 60 },
      { x: 600, y: 60 }
    ]
  })
  
  selectedPlot.value = plots.value[plots.value.length - 1]
  plot_name.value = ''
}

const clearForm = () => {
  if (register_plot.value) {
    plots.value.pop()
  }
  plot_name.value = ''
  edit_plot.value = false
  register_plot.value = false
  edit_plot_name.value = false
  selectedPlot.value = null
  selected_node.value = { plotIndex: null, nodeIndex: null, label: 'none' }
}

const addNode = () => {
  if (!selectedPlot.value || selectedPlot.value.status === 'sold') return

  const plotIdx = plots.value.findIndex(p => p.id === selectedPlot.value.id)
  if (plotIdx === -1) return

  const coords = plots.value[plotIdx].coordinates
  if (!coords.length) return

  const last = coords[coords.length - 1]

  coords.push({
    x: last.x + 20,
    y: last.y + 20
  })

  const newIndex = coords.length - 1

  selected_node.value = {
    plotIndex: plotIdx,
    nodeIndex: newIndex,
    label: `${selectedPlot.value.name}-${newIndex}`
  }

  longitudeValue.value = coords[newIndex].x
  latitudeValue.value = coords[newIndex].y
}

const handleSvgClick = (event) => {
  if ((!register_plot.value && !edit_plot.value) || selected_node.value.plotIndex === null || selected_node.value.nodeIndex === null) return
  if (!selectedPlot.value) return

  const nodePlotIndex = selected_node.value.plotIndex
  const selectedPlotIndex = plots.value.findIndex(p => p.id === selectedPlot.value.id)
  if (nodePlotIndex !== selectedPlotIndex) return

  const svg = event.currentTarget
  const point = svg.createSVGPoint()
  point.x = event.clientX
  point.y = event.clientY
  const svgPoint = point.matrixTransform(svg.getScreenCTM().inverse())

  const pIdx = selected_node.value.plotIndex
  const nIdx = selected_node.value.nodeIndex

  if (pIdx !== null && nIdx !== null) {
    // ✅ Add offsets back to store real coordinates
    plots.value[pIdx].coordinates[nIdx].x = svgPoint.x + xOffset.value
    plots.value[pIdx].coordinates[nIdx].y = svgPoint.y + yOffset.value
    longitudeValue.value = plots.value[pIdx].coordinates[nIdx].x
    latitudeValue.value = plots.value[pIdx].coordinates[nIdx].y
  }
}


// API Functions
const getPlots = async () => {
  try {
    const response = await axiosInstance.get(`plots`)
    plots.value = response.data.map(plot => ({
      ...plot,
      coordinates: plot.coordinates.map(coord => ({
        ...coord,
        x: parseFloat(coord.x),
        y: parseFloat(coord.y)
      }))
    }))
  } catch (error) {
    console.error('Error fetching plots:', error)
    showError(error.message)
    console.log(error)
  }
}

const registerPlot = async () => {
  const newlyAddedPlot = plots.value[plots.value.length - 1]
  newlyAddedPlot.coordinates.forEach(coord => {
    coord.x = Number(coord.x)
    coord.y = Number(coord.y)
  })

  try {
    await axiosInstance.post(`plots`, newlyAddedPlot)
    showMessage('Plot registered successfully')
    getPlots()
  } catch (error) {
    console.error('Error registering plot:', error)
    showError(error.message)
    console.log(error)
  } finally {
    clearForm()
  }
}

const updatePlot = async () => {
  const payload = {
    name: selectedPlot.value.name,
    coordinates: selectedPlot.value.coordinates.map(coord => ({
      ...coord,
      x: Number(coord.x),
      y: Number(coord.y)
    }))
  }
  
  try {
    await axiosInstance.put(`plots/${selectedPlot.value.id}`, payload)
    showMessage('Plot updated successfully')
    getPlots()
  } catch (error) {
    showError(error.message)
    console.log(error)
  } finally {
    clearForm()
  }
}

const sellPlot = async () => {
  const payload = {
    color_fill: "#fca7a7",
    color_stroke: "#dc3545",
    status: "sold"
  }
  
  try {
    await axiosInstance.put(`plots/${selectedPlot.value.id}`, payload)
    showMessage('Plot marked as sold')
    getPlots()
  } catch (error) {
      showError(error.message)
    console.log(error)
  } finally {
    clearForm()
  }
}


// Watchers
watch([latitudeValue, longitudeValue], () => {
  const pIdx = selected_node.value.plotIndex
  const nIdx = selected_node.value.nodeIndex
  if (pIdx !== null && nIdx !== null) {
    plots.value[pIdx].coordinates[nIdx].x = longitudeValue.value
    plots.value[pIdx].coordinates[nIdx].y = latitudeValue.value
  }
})

watch(scaleValue, (newVal) => {
  if (latitudeValue.value > newVal) latitudeValue.value = newVal
  if (longitudeValue.value > newVal) longitudeValue.value = newVal
})

watch(selected_node, (newVal) => {
  if (newVal.nodeIndex !== null && selectedPlot.value) {
    distanceToNextInput.value = getDistanceToNextNode().toFixed(1)
    distanceToPreviousInput.value = getDistanceToPreviousNode().toFixed(1)
  }
})


const downloadSvg = () => {
  const svg = document.querySelector('.plot-svg')
  if (!svg) return

  const serializer = new XMLSerializer()
  const svgStr = serializer.serializeToString(svg)
  const blob = new Blob([svgStr], { type: 'image/svg+xml' })
  const url = URL.createObjectURL(blob)

  const a = document.createElement('a')
  a.href = url
  a.download = 'plots.svg'
  a.click()

  URL.revokeObjectURL(url)
}

const xOffset = computed(() => {
  if (!plots.value.length) return 0
  let minX = Infinity
  plots.value.forEach(plot => {
    plot.coordinates.forEach(p => {
      if (p.x < minX) minX = p.x
    })
  })
  return minX - 50 // 50px left padding
})

const yOffset = computed(() => {
  if (!plots.value.length) return 0
  let minY = Infinity
  plots.value.forEach(plot => {
    plot.coordinates.forEach(p => {
      if (p.y < minY) minY = p.y
    })
  })
  return minY - 50 // 50px top padding
})


const getConnectorClass = (type) => {
  if (type === 'CONNECTOR') return 'text-danger'
  if (type === 'BREAK') return 'text-primary'
  if (type === 'INDICATOR') return 'text-warning'
  return 'text-secondary'
}


onMounted(() => {
  getPlots()
  
  // Mouse wheel zoom
  const wrapper = document.querySelector('.svg-scroll-wrapper')
  wrapper?.addEventListener('wheel', (e) => {
    e.preventDefault()
    if (e.deltaY < 0) zoomIn()
    else zoomOut()
  }, { passive: false })
})

</script>



